# Sensitive field detection
# --------------------------------------------------------------------------- #


# Field-name keywords matched against the lowered field name; each contributes
# a "name:<kind>" evidence token.
_NAME_KEYWORDS: tuple[tuple[str, str], ...] = (
    ("email", "email"),
    ("phone", "phone"),
    ("idcard", "idcard"),
)

# Only fields declared with one of these types take part in sample matching.
_SAMPLE_MATCH_TYPES = ("string", "integer")


def _is_ascii_digits(text: str) -> bool:
    return bool(text) and all("0" <= char <= "9" for char in text)


def _is_phone_number(text: str) -> bool:
    return len(text) == 11 and text.startswith("1") and _is_ascii_digits(text)


def _is_idcard_number(text: str) -> bool:
    """15- or 18-digit ID-card number; the final character may be the letter X."""
    if len(text) == 15:
        return _is_ascii_digits(text)
    if len(text) == 18:
        return _is_ascii_digits(text[:-1]) and (
            _is_ascii_digits(text[-1]) or text[-1] == "X"
        )
    return False


def _string_sample_hits(value: str) -> set[str]:
    hits: set[str] = set()
    if value.count("@") == 1:
        local, _, domain = value.partition("@")
        if local and domain:
            hits.add("email")
    if _is_phone_number(value):
        hits.add("phone")
    if _is_idcard_number(value):
        hits.add("idcard")
    return hits


def _detect_sensitive_evidence(
    field_name: str, field_type: str, samples: list[Any]
) -> tuple[list[str], str]:
    """Evidence tokens and confidence flag for one field.

    The lowered field name contributes ``name:<kind>`` tokens; the samples
    contribute ``value:<kind>`` tokens, but only when the declared field type
    is string or integer. A hit on both sides yields ``high`` confidence;
    anything else (one side only, or no hit at all) yields ``low``.
    """
    lowered = field_name.lower()
    hits = {f"name:{kind}" for keyword, kind in _NAME_KEYWORDS if keyword in lowered}

    if field_type in _SAMPLE_MATCH_TYPES:
        value_kinds: set[str] = set()
        for sample in samples:
            # Booleans and nulls never participate; an integer is matched as
            # its decimal digit string (phone and id-card only); other numbers
            # (floats) match nothing.
            if isinstance(sample, bool) or sample is None:
                continue
            if isinstance(sample, int):
                digits = str(sample)
                if _is_phone_number(digits):
                    value_kinds.add("phone")
                if _is_idcard_number(digits):
                    value_kinds.add("idcard")
            elif isinstance(sample, str):
                value_kinds |= _string_sample_hits(sample)
        hits |= {f"value:{kind}" for kind in value_kinds}

    has_name_hit = any(token.startswith("name:") for token in hits)
    has_value_hit = any(token.startswith("value:") for token in hits)
    confidence = "high" if has_name_hit and has_value_hit else "low"
    return sorted(hits), confidence


