def register_sensitive_detection(
    conn: sqlite3.Connection,
    dataset_name: str,
    version_number: int,
    field: str,
    samples: list[Any],
    rerun: bool,
    *,
    query_keys: tuple[str, ...] = (),
) -> dict:
    """Register (or, with ``rerun``, refresh) the detection record of a field.

    One record is kept per (version, field): a second registration without
    ``rerun`` is a 409, while a rerun rewrites only the evidence and the
    confidence flag, keeping the id and the creation time. A field with no
    hits is stored with empty evidence and low confidence so it can be
    reviewed and re-run later. Sample values are never persisted.
    """
    dataset = require_dataset(conn, dataset_name)
    version_row = _require_schema_version(conn, dataset, version_number)
    if query_keys:
        raise RequestInvalidError(
            "The sensitive detection endpoint does not accept query parameters"
        )

    clean_field = field.strip()
    if not clean_field:
        raise RequestInvalidError("Field name must not be empty")

    field_row = conn.execute(
        "SELECT name, type FROM schema_fields WHERE version_id = ? AND name = ?",
        (version_row["id"], clean_field),
    ).fetchone()
    if field_row is None:
        raise NotFoundError(
            f"Field '{clean_field}' does not exist in version "
            f"{version_number} of dataset '{dataset_name}'"
        )

    evidence, confidence = _detect_sensitive_evidence(
        field_row["name"], field_row["type"], samples
    )
    stored_evidence = json.dumps(evidence)

    existing = conn.execute(
        "SELECT id FROM sensitive_detections WHERE version_id = ? AND field = ?",
        (version_row["id"], clean_field),
    ).fetchone()

    if existing is not None:
        if not rerun:
            raise ConflictError(
                f"A sensitive detection record for field '{clean_field}' "
                f"already exists for version {version_number} of dataset "
                f"'{dataset_name}'; pass 'rerun' to refresh it"
            )
        conn.execute(
            "UPDATE sensitive_detections SET evidence = ?, confidence = ? "
            "WHERE id = ?",
            (stored_evidence, confidence, existing["id"]),
        )
        detection_id = existing["id"]
    else:
        try:
            cursor = conn.execute(
                "INSERT INTO sensitive_detections ("
                "version_id, field, evidence, confidence, created_at"
                ") VALUES (?, ?, ?, ?, ?)",
                (
                    version_row["id"],
                    clean_field,
                    stored_evidence,
                    confidence,
                    utc_now_iso(),
                ),
            )
        except sqlite3.IntegrityError as exc:
            raise ConflictError(
                f"A sensitive detection record for field '{clean_field}' "
                f"already exists for version {version_number} of dataset "
                f"'{dataset_name}'; pass 'rerun' to refresh it"
            ) from exc
        detection_id = cursor.lastrowid

    row = conn.execute(
        "SELECT * FROM sensitive_detections WHERE id = ?", (detection_id,)
    ).fetchone()
    return _sensitive_detection_row_to_dict(
        row, dataset["name"], version_row["version"]
    )


def list_sensitive_detections(
    conn: sqlite3.Connection,
    dataset_name: str,
    version_number: int,
    *,
    body: bytes = b"",
    query_keys: tuple[str, ...] = (),
) -> list[dict]:
    """Every detection record of one version, ordered by id ascending."""
    dataset, version_row = _require_evaluation_path(
        conn,
        dataset_name,
        version_number,
        body=body,
        query_keys=query_keys,
